html:
{%- set invoice_cashier = get_invoice_cashier(doc) -%}
{%- set company_tax_id = frappe.db.get_value("Company", doc.company, "tax_id") or "" -%}
<style>

/* =========================================================
   PAGE
========================================================= */

@page {
    size: 80mm 297mm !important;
    margin: 0 !important;
}

* {
    box-sizing: border-box !important;
}

html,
body,
.print-format {
    width: 80mm !important;
    min-width: 80mm !important;
    max-width: 80mm !important;

    margin: 0 !important;
    padding: 0 !important;

    background: #fff !important;

    color: #000 !important;

    font-family:
        "Noto Naskh Arabic",
        "DejaVu Sans",
        Arial,
        sans-serif !important;
}


/* =========================================================
   RESET FRAPPE
========================================================= */

.print-format table {
    width: 100% !important;

    margin: 0 !important;

    border-collapse: collapse !important;
    border-spacing: 0 !important;
}

.print-format table,
.print-format thead,
.print-format tbody,
.print-format tr,
.print-format td,
.print-format th {
    background: transparent !important;
    box-shadow: none !important;
}

.print-format td,
.print-format th {
    border: none !important;
}


/* =========================================================
   RECEIPT
========================================================= */

.booking-receipt {
    width: 74mm !important;
    max-width: 74mm !important;

    margin: 0 auto !important;
    padding: 2mm 0 3mm 0 !important;

    direction: rtl !important;
    text-align: right !important;

    overflow: hidden !important;

    color: #000 !important;

    font-size: 16px !important;
    font-weight: 700 !important;

    line-height: 1.55;
}

.booking-receipt *:not(img) {
    color: #000 !important;
    font-weight: 700 !important;
}


/* =========================================================
   NUMBERS
========================================================= */

.number {
    direction: ltr !important;
    unicode-bidi: isolate !important;

    font-family:
        "DejaVu Sans",
        Arial,
        sans-serif !important;
}


/* =========================================================
   HEADER
========================================================= */

.company-name {
    text-align: center !important;

    font-size: 18px !important;

    line-height: 1.5;

    margin: 0 0 3px 0;
}


.logo {
    text-align: center !important;

    margin: 2px 0 4px 0;
}


.logo img {
    display: block;

    width: auto !important;
    height: auto !important;

    max-width: 38mm !important;
    max-height: 20mm !important;

    margin: 0 auto !important;
}


.booking-title {
    text-align: center !important;

    font-size: 18px !important;

    margin: 4px 0 7px 0;
}


/* =========================================================
   DIVIDERS
========================================================= */

.divider {
    width: 100%;

    border-top: 1px dashed #000;

    margin: 7px 0;
}


.solid-divider {
    width: 100%;

    border-top: 2px solid #000;

    margin: 7px 0;
}


/* =========================================================
   BOOKING INFO
========================================================= */

.info-table {
    width: 100% !important;

    table-layout: fixed !important;

    direction: rtl !important;
}


.info-table td {
    padding: 2px 1px !important;

    vertical-align: top !important;

    line-height: 1.45;
}


.info-label {
    width: 35% !important;

    text-align: right !important;

    white-space: nowrap !important;
}


.info-value {
    width: 65% !important;

    text-align: right !important;

    overflow-wrap: anywhere !important;
    word-break: break-word !important;
}


.info-number {
    direction: ltr !important;
    unicode-bidi: isolate !important;

    text-align: left !important;

    padding-left: 2mm !important;

    white-space: normal !important;
}


/* =========================================================
   NOTES
========================================================= */

.booking-notes-print {
    margin: 3px 0;
    padding: 2px 0;
}

.booking-notes-label {
    margin-bottom: 1px;
}

.booking-notes-value {
    margin: 0;
    line-height: 1.35;
    white-space: pre-wrap;
    overflow-wrap: anywhere;
    word-break: break-word;
}


/* =========================================================
   ITEMS
========================================================= */

.items {
    width: 100% !important;

    table-layout: fixed !important;

    direction: rtl !important;
}


.items thead th {
    padding: 4px 1px !important;

    border-top: 1px solid #000 !important;
    border-bottom: 1px solid #000 !important;

    text-align: center !important;

    vertical-align: middle !important;
}


.items .item-column {
    width: 44% !important;

    text-align: right !important;
}


.items .qty-column {
    width: 14% !important;
}


.items .price-column {
    width: 20% !important;
}


.items .total-column {
    width: 22% !important;
}


.items tbody td {
    padding: 5px 1px !important;

    vertical-align: top !important;

    border-bottom: 1px dashed #bbb !important;
}


.items tbody td.item-column {
    text-align: right !important;

    line-height: 1.5;

    overflow-wrap: anywhere !important;
}


.items tbody td.qty-column,
.items tbody td.price-column,
.items tbody td.total-column {
    text-align: center !important;

    direction: ltr !important;
    unicode-bidi: isolate !important;

    white-space: nowrap !important;

    font-family:
        "DejaVu Sans",
        Arial,
        sans-serif !important;
}


.item-name {
    line-height: 1.5;
}

.item-description {
    margin: 1px 0;
    padding: 0;
    font-size: 13px !important;
    line-height: 1.2;
    white-space: normal;
    overflow-wrap: anywhere;
    word-break: break-word;
}


/* =========================================================
   TOTALS
========================================================= */

.summary-table {
    width: 100% !important;

    table-layout: fixed !important;

    direction: rtl !important;
}


.summary-table td {
    padding: 3px 1px !important;

    vertical-align: middle !important;
}


.summary-label {
    width: 57% !important;

    text-align: right !important;
}


.summary-value {
    width: 43% !important;

    text-align: left !important;

    direction: ltr !important;
    unicode-bidi: isolate !important;

    padding-left: 2mm !important;

    white-space: nowrap !important;

    font-family:
        "DejaVu Sans",
        Arial,
        sans-serif !important;
}


/* الإجمالي */

.grand-total td {
    border-top: 1px solid #000 !important;
    border-bottom: 1px solid #000 !important;

    padding-top: 6px !important;
    padding-bottom: 6px !important;

    font-size: 17px !important;
}


/* المدفوع والمتبقي */

.paid-row td {
    padding-top: 5px !important;
}


.remaining-row td {
    font-size: 17px !important;

    padding-top: 5px !important;
}


/* =========================================================
   FOOTER
========================================================= */

.footer {
    border-top: 2px solid #000 !important;

    margin-top: 10px;

    padding-top: 7px;

    text-align: center !important;

    font-size: 14px !important;
}


/* =========================================================
   PRINT
========================================================= */

@media print {

    @page {
        size: 80mm 297mm !important;
        margin: 0 !important;
    }

    html,
    body,
    .print-format {
        width: 80mm !important;
        min-width: 80mm !important;
        max-width: 80mm !important;

        margin: 0 !important;
        padding: 0 !important;
    }

    .booking-receipt {
        width: 74mm !important;
        max-width: 74mm !important;

        margin: 0 auto !important;
    }

    tr,
    td,
    th {
        page-break-inside: avoid !important;
        break-inside: avoid !important;
    }
}

</style>


{# =========================================================
   DATA
========================================================= #}

{%- set symbol =
    frappe.db.get_value(
        'Currency',
        doc.currency,
        'symbol'
    ) or doc.currency
-%}


{%- set logo =
    frappe.db.get_value(
        'Company',
        doc.company,
        'company_logo'
    )
-%}


{# =========================================================
   BOOKING PAYMENTS
========================================================= #}

{%- set booking_payments =
    frappe.get_all(
        'Payment Entry',
        filters={
            'custom_booking_invoice': doc.name,
            'docstatus': 1,
            'payment_type': 'Receive'
        },
        fields=[
            'paid_amount',
            'base_paid_amount'
        ]
    )
-%}


{%- set paid =
    booking_payments
    | sum(attribute='paid_amount')
-%}


{%- if
    doc.party_account_currency != doc.currency
    and
    doc.currency != doc.company_currency
    and
    doc.conversion_rate
-%}

    {%- set paid =
        (
            booking_payments
            | sum(attribute='base_paid_amount')
        )
        /
        doc.conversion_rate
    -%}

{%- endif -%}


{%- set remaining =
    doc.grand_total - paid
-%}


{%- if remaining < 0 -%}
    {%- set remaining = 0 -%}
{%- endif -%}



<!-- ========================================================
     RECEIPT
======================================================== -->

<div class="booking-receipt">


    <!-- ====================================================
         COMPANY
    ===================================================== -->

    <div class="company-name">
        {{ doc.company }}
    </div>


    {% if logo %}

    <div class="logo">

        <img
            src="{{ logo }}"
            alt=""
        >

    </div>

    {% endif %}


    {% if company_tax_id %}
    <div style="text-align:center;font-size:12px;line-height:1.4;">
        الرقم الضريبي: <span class="number">{{ company_tax_id | e }}</span>
    </div>
    {% endif %}
    <div data-cashier-info dir="rtl" style="text-align:center;font-size:12px;line-height:1.4;">{{ invoice_cashier.text | e }}</div>

    <div class="booking-title">
        فاتورة حجز
    </div>



    <!-- ====================================================
         BOOKING INFORMATION
    ===================================================== -->

    <table class="info-table">

        <tbody>


            <tr>

                <td class="info-label">
                    رقم الحجز
                </td>

                <td class="info-value info-number">
                    {{ doc.name }}
                </td>

            </tr>


            <tr>

                <td class="info-label">
                    العميل
                </td>

                <td class="info-value">
                    {{ doc.customer_name or doc.customer }}
                </td>

            </tr>


            <tr>

                <td class="info-label">
                    التاريخ
                </td>

                <td class="info-value info-number">

                    {{
                        frappe.utils.formatdate(
                            doc.posting_date,
                            "dd-MM-yyyy"
                        )
                    }}

                </td>

            </tr>


            <tr>

                <td class="info-label">
                    تاريخ التسليم
                </td>

                <td class="info-value info-number">

                    {% if doc.custom_delivery_date %}

                        {{
                            frappe.utils.formatdate(
                                doc.custom_delivery_date,
                                "dd-MM-yyyy"
                            )
                        }}

                    {% else %}

                        -

                    {% endif %}

                </td>

            </tr>


        </tbody>

    </table>


    {% if doc.remarks %}
    <div class="booking-notes-print">
        <div class="booking-notes-label">ملاحظات</div>
        <div class="booking-notes-value">{{ doc.remarks }}</div>
    </div>
    {% endif %}


    <div class="divider"></div>



    <!-- ====================================================
         ITEMS
    ===================================================== -->

    <table class="items">


        <thead>

            <tr>

                <th class="item-column">
                    الصنف
                </th>

                <th class="qty-column">
                    الكمية
                </th>

                <th class="price-column">
                    السعر
                </th>

                <th class="total-column">
                    الإجمالي
                </th>

            </tr>

        </thead>


        <tbody>


            {% for item in doc.items %}

            <tr>


                <td class="item-column">

                    <div class="item-name">

                        {{
                            item.item_name
                            or
                            item.item_code
                        }}

                    </div>

                    {%- set item_description = frappe.utils.strip_html(item.description or '') | trim -%}
                    {% if item_description %}
                    <div class="item-description">{{ item_description }}</div>
                    {% endif %}

                </td>


                <td class="qty-column">

                    {{
                        "%.2f"|format(
                            item.qty or 0
                        )
                    }}

                </td>


                <td class="price-column">

                    {{
                        "%.2f"|format(
                            item.rate or 0
                        )
                    }}

                </td>


                <td class="total-column">

                    {{
                        "%.2f"|format(
                            item.amount or 0
                        )
                    }}

                </td>


            </tr>

            {% endfor %}


        </tbody>

    </table>



    <!-- ====================================================
         TOTALS
    ===================================================== -->

    <table class="summary-table">

        <tbody>


            <tr>

                <td class="summary-label">
                    المجموع الفرعي
                </td>

                <td class="summary-value">

                    {{
                        "%.2f"|format(
                            doc.net_total or 0
                        )
                    }}

                    {{ symbol }}

                </td>

            </tr>



            <tr>

                <td class="summary-label">
                    الضريبة
                </td>

                <td class="summary-value">

                    {{
                        "%.2f"|format(
                            doc.total_taxes_and_charges or 0
                        )
                    }}

                    {{ symbol }}

                </td>

            </tr>



            <tr class="grand-total">

                <td class="summary-label">
                    الإجمالي
                </td>

                <td class="summary-value">

                    {{
                        "%.2f"|format(
                            doc.grand_total or 0
                        )
                    }}

                    {{ symbol }}

                </td>

            </tr>



            <tr class="paid-row">

                <td class="summary-label">
                    المدفوع
                </td>

                <td class="summary-value">

                    {{
                        "%.2f"|format(
                            paid
                        )
                    }}

                    {{ symbol }}

                </td>

            </tr>



            <tr class="remaining-row">

                <td class="summary-label">
                    المتبقي
                </td>

                <td class="summary-value">

                    {{
                        "%.2f"|format(
                            remaining
                        )
                    }}

                    {{ symbol }}

                </td>

            </tr>


        </tbody>

    </table>



    <!-- ====================================================
         FOOTER
    ===================================================== -->

    <div class="footer">
        شكراً لكم
    </div>


</div>

{# ==========================================================
   HELO & HELO SHOP
   Payment Entry - Thermal Receipt
   Paper: 80mm x 297mm

   Receive = سند قبض
   Pay     = سند صرف
========================================================== #}

{% set company = frappe.get_doc("Company", doc.company) %}

{% set is_receive = doc.payment_type == "Receive" %}
{% set is_pay = doc.payment_type == "Pay" %}

{% set party_name = doc.party_name or doc.party or "—" %}

{% if is_receive %}
    {% set amount = doc.received_amount or doc.paid_amount or 0 %}
    {% set currency = doc.paid_to_account_currency or doc.paid_from_account_currency or "" %}
{% else %}
    {% set amount = doc.paid_amount or doc.received_amount or 0 %}
    {% set currency = doc.paid_from_account_currency or doc.paid_to_account_currency or "" %}
{% endif %}


<div class="helo-payment" dir="rtl">


    <!-- ========================
         LOGO
    ========================= -->

    {% if company.company_logo %}

    <div class="logo">

        <img
            src="{{ company.company_logo }}"
            alt="{{ company.company_name }}"
        >

    </div>

    {% endif %}



    <!-- ========================
         COMPANY
    ========================= -->

    <div class="shop-name">

        {{ company.company_name or doc.company }}

    </div>


    {% if company.phone_no %}

    <div class="shop-info" dir="ltr">

        {{ company.phone_no }}

    </div>

    {% endif %}



    <div class="divider"></div>



    <!-- ========================
         DOCUMENT TYPE
    ========================= -->

    <div class="voucher-title">


        {% if is_receive %}

            سند قبض

            <small>
                RECEIPT
            </small>


        {% elif is_pay %}

            سند صرف

            <small>
                PAYMENT
            </small>


        {% else %}

            سند مالي

            <small>
                PAYMENT ENTRY
            </small>

        {% endif %}


    </div>



    <!-- ========================
         AMOUNT
    ========================= -->

    <div class="amount-label">

        المبلغ

    </div>


    <div class="amount">

        {{ frappe.utils.fmt_money(amount, currency=currency) }}

    </div>



    <div class="divider"></div>



    <!-- ========================
         DETAILS
    ========================= -->

    <table class="details-table">


        <!-- PARTY -->

        <tr>

            <th>

                {% if is_receive %}

                    استلمنا من

                {% elif is_pay %}

                    تم الدفع إلى

                {% else %}

                    الاسم

                {% endif %}

            </th>


            <td class="party-value">

                {{ party_name }}

            </td>

        </tr>



        <!-- DATE -->

        <tr>

            <th>
                التاريخ
            </th>

            <td dir="ltr">

                {% if doc.posting_date %}

                    {{
                        frappe.utils.formatdate(
                            doc.posting_date,
                            "dd/MM/yyyy"
                        )
                    }}

                {% else %}

                    —

                {% endif %}

            </td>

        </tr>



        <!-- TIME -->

        {% if doc.creation %}

        <tr>

            <th>
                الوقت
            </th>

            <td dir="ltr">

                {{
                    frappe.utils.format_time(
                        doc.creation,
                        "HH:mm"
                    )
                }}

            </td>

        </tr>

        {% endif %}



        <!-- PAYMENT METHOD -->

        {% if doc.mode_of_payment %}

        <tr>

            <th>
                طريقة الدفع
            </th>

            <td>

                {{ doc.mode_of_payment }}

            </td>

        </tr>

        {% endif %}



        <!-- REFERENCE -->

        {% if doc.reference_no %}

        <tr>

            <th>
                رقم المرجع
            </th>

            <td dir="ltr">

                {{ doc.reference_no }}

            </td>

        </tr>

        {% endif %}



        <!-- DOCUMENT NUMBER -->

        <tr>

            <th>
                رقم السند
            </th>

            <td
                class="document-number"
                dir="ltr"
            >

                {{ doc.name }}

            </td>

        </tr>


    </table>



    <!-- ========================
         REMARKS
    ========================= -->

    {% if doc.custom_notes %}

    <div class="divider"></div>


    <div class="remarks-title">

        البيان

    </div>


    <div class="remarks">

        {{ doc.custom_notes }}

    </div>

    {% endif %}



    <!-- ========================
         REFERENCES
    ========================= -->

    {% if doc.references and doc.references|length > 0 %}


    <div class="references">


        {% for row in doc.references %}


            {% if row.reference_name %}


            <div class="reference-row">


                <span dir="ltr">

                    {{ row.reference_name }}

                </span>


                {% if row.allocated_amount %}

                <strong dir="ltr">

                    {{
                        frappe.utils.fmt_money(
                            row.allocated_amount,
                            currency=currency
                        )
                    }}

                </strong>

                {% endif %}


            </div>


            {% endif %}


        {% endfor %}


    </div>


    {% endif %}



    <!-- ========================
         FOOTER
    ========================= -->

    <div class="footer">

        شكراً لتعاملكم معنا

        <div class="footer-en">

            Thank You

        </div>

    </div>


</div>



<style>


/* ==========================================================
   THERMAL PAPER
========================================================== */

@page {

    size: 80mm 297mm;

    margin: 0 !important;

}



* {

    box-sizing: border-box !important;

}



html,
body {

    width: 80mm !important;

    max-width: 80mm !important;

    margin: 0 !important;

    padding: 0 !important;

    background: #fff !important;

}



.print-format {

    width: 80mm !important;

    max-width: 80mm !important;

    min-width: 80mm !important;

    margin: 0 !important;

    padding: 0 !important;

}



/* ==========================================================
   RECEIPT

   IMPORTANT:
   Physical paper = 80mm
   Safe printable content = 72mm
========================================================== */

.helo-payment {

    display: block;

    width: 72mm !important;

    max-width: 72mm !important;

    min-width: 72mm !important;

    margin: 0 auto !important;

    padding:
        2mm
        1mm
        3mm !important;

    color: #000;

    background: #fff;

    direction: rtl;

    font-family:
        "Noto Sans Arabic",
        "DejaVu Sans",
        Tahoma,
        Arial,
        sans-serif;

    font-size: 11px;

    line-height: 1.35;

    overflow: hidden;

}



/* ==========================================================
   LOGO
========================================================== */

.logo {

    width: 100%;

    margin:
        0
        auto
        1mm;

    padding: 0;

    text-align: center;

}



.logo img {

    display: block;

    width: auto;

    max-width: 24mm;

    max-height: 17mm;

    margin: 0 auto;

    object-fit: contain;

}



/* ==========================================================
   COMPANY
========================================================== */

.shop-name {

    width: 100%;

    margin: 0;

    padding: 0;

    text-align: center;

    font-size: 14px;

    font-weight: 900;

    line-height: 1.25;

    overflow-wrap: anywhere;

}



.shop-info {

    width: 100%;

    margin-top: .5mm;

    text-align: center;

    font-size: 9px;

}



/* ==========================================================
   DIVIDER
========================================================== */

.divider {

    width: 100%;

    height: 0;

    margin:
        2mm
        0;

    padding: 0;

    border: 0;

    border-top:
        1px
        dashed
        #777;

}



/* ==========================================================
   TITLE
========================================================== */

.voucher-title {

    width: 100%;

    margin: 0;

    padding: 0;

    text-align: center;

    font-size: 18px;

    font-weight: 900;

    line-height: 1.15;

}



.voucher-title small {

    display: block;

    margin-top: .5mm;

    direction: ltr;

    text-align: center;

    font-size: 6px;

    font-weight: 800;

    letter-spacing: .5px;

}



/* ==========================================================
   AMOUNT
========================================================== */

.amount-label {

    width: 100%;

    margin-top: 2mm;

    text-align: center;

    font-size: 10px;

    font-weight: 800;

}



.amount {

    width: 100%;

    margin-top: 1mm;

    padding:
        2mm
        1mm;

    border:
        1.5px
        solid
        #000;

    border-radius: 1.5mm;

    direction: ltr;

    text-align: center;

    font-size: 20px;

    font-weight: 900;

    line-height: 1.15;

    white-space: normal;

    overflow-wrap: anywhere;

}



/* ==========================================================
   DETAILS TABLE

   TABLE USED INSTEAD OF FLEX
   FOR BETTER WKHTMLTOPDF / THERMAL SUPPORT
========================================================== */

.details-table {

    width: 100% !important;

    max-width: 100% !important;

    margin: 0;

    padding: 0;

    border: 0;

    border-collapse: collapse;

    border-spacing: 0;

    table-layout: fixed;

    direction: rtl;

}



.details-table tr {

    width: 100%;

    border-bottom:
        1px
        dotted
        #999;

}



.details-table tr:last-child {

    border-bottom: 0;

}



