            فاتورة ملغاة - CANCELLED
        </div>
    {% elif doc.docstatus == 0 %}
        <div class="hala-status">
            مسودة - DRAFT
        </div>
    {% endif %}


    {# HEADER #}

    <div class="hala-header">

        <table class="hala-header-table">
            <tr>

                <td class="hala-header-company">

                    {% if company_logo  %}
                        <div style="margin-bottom:6px;">
                            <img
                                src="{{ company_logo }}"
                                style="max-width:150px;max-height:55px;width:auto;height:auto;"
                            >
                        </div>
                    {% endif %}

                    <div class="hala-company-name">
                        {{ doc.company }}
                    </div>

                    {% if company_tax_id %}
                        <div class="hala-company-tax">
                            الرقم الضريبي / VAT No:
                            <span class="num">{{ company_tax_id }}</span>
                        </div>
                    {% endif %}
                    <div class="hala-company-tax" data-cashier-info dir="rtl">{{ invoice_cashier.text | e }}</div>

                </td>

                <td class="hala-header-title">

                    <div class="hala-title">
                        فاتورة ضريبية
                    </div>

                    <div class="hala-title-en">
                        TAX INVOICE
                    </div>

                    <div class="hala-invoice-no">
                        <span class="num">{{ doc.name }}</span>
                    </div>

                </td>

            </tr>
        </table>

    </div>


    {# INVOICE INFORMATION #}

    <table class="hala-meta">
        <tr>

            <td>
                <div class="hala-meta-label">
                    رقم الفاتورة / Invoice No.
                </div>
                <div class="hala-meta-value">
                    <span class="num">{{ doc.name }}</span>
                </div>
            </td>

            <td>
                <div class="hala-meta-label">
                    تاريخ الفاتورة / Invoice Date
                </div>
                <div class="hala-meta-value">
                    <span class="num">
                        {{ frappe.utils.formatdate(doc.posting_date, "dd-MM-yyyy") }}
                    </span>
                </div>
            </td>

            <td>
                <div class="hala-meta-label">
                    تاريخ التسليم / Delivery Date
                </div>
                <div class="hala-meta-value">
                    <span class="num">
                        {% if doc.custom_delivery_date %}
                            {{ frappe.utils.formatdate(doc.custom_delivery_date, "dd-MM-yyyy") }}
                        {% else %}
                            -
                        {% endif %}
                    </span>
                </div>
            </td>

            <td>
                <div class="hala-meta-label">
                    وقت التسليم / Delivery Time
                </div>
                <div class="hala-meta-value">
                    <span class="num">{{ frappe.utils.format_time(doc.posting_time, "HH:mm:ss") if doc.posting_time else "-" }}</span>
                </div>
            </td>

        </tr>
    </table>


    {# SELLER AND BUYER #}

