                            {% if seller.address_line1 %}
                                <div>{{ seller.address_line1 }} . 
                            {% endif %}

                            {% if seller.address_line2 %}
                                {{ seller.address_line2 }} .
                            {% endif %}

                          
                                {{ seller.city or "" }} . 
                              

                            {% if seller.country %}
                                {{ seller.country }}</div>
                            {% endif %}

                            {% if seller.phone %}
                                <div>
                                    الهاتف:
                                    <span class="num">{{ seller.phone }}</span>
                                </div>
                            {% endif %}

                            {% if seller.email_id %}
                                <div>
                                    {{ seller.email_id }}
                                </div>
