                                    <span class="num">
                                        {{ tax.get_formatted("tax_amount") }}
                                    </span>
                                </td>
                            </tr>
                        {% endif %}
                    {% endfor %}

                    <tr class="hala-grand">
                        <td>
                            الإجمالي شامل الضريبة
                           
                        </td>

                        <td>
                            <span class="num">
                                {{ doc.get_formatted("grand_total", doc) }}
                            </span>
                        </td>
                    </tr>

                    {% if doc.rounded_total and doc.rounded_total != doc.grand_total %}
                        <tr>
                            <td>الإجمالي بعد التقريب</td>
                            <td>
                                <span class="num">
                                    {{ doc.get_formatted("rounded_total", doc) }}
                                </span>
                            </td>
                        </tr>
                    {% endif %}

                   

                    {% if tendered is not none %}
                        <tr>
                            <td>المبلغ المستلم من العميل</td>
                            <td>
                                <span class="num">
                                    {{ frappe.utils.fmt_money(tendered, currency=doc.currency) }}
                                </span>
                            </td>
                        </tr>

                        {% if change_amount > 0 %}
                            <tr>
                                <td>الباقي المرجع للعميل</td>
                                <td>
                                    <span class="num">
                                        {{ frappe.utils.fmt_money(change_amount, currency=doc.currency) }}
                                    </span>
                                </td>
                            </tr>
                        {% endif %}
                    {% endif %}

                  
                </table>

            </td>


            <td class="hala-summary-words">

                <div class="hala-words-box">

                    <div class="hala-words-label">
                        الإجمالي كتابةً :
                    
                        {{ doc.in_words or "" }}
                    </div>

                </div>

                {% if doc.remarks %}
                    <div class="hala-words-box">

                        <div class="hala-words-label">
                            ملاحظات / Remarks
                        </div>

                        <div>
                            {{ doc.remarks }}
                        </div>

                    </div>
                {% endif %}

                {% if doc.get("po_no") %}
                    <div class="hala-words-box">
                        <div class="hala-words-label">
                            رقم أمر شراء العميل
                        </div>
                        <div class="bold">
                            <span class="num">{{ doc.po_no }}</span>
                        </div>
                    </div>
                {% endif %}



 {% if doc.name and doc.docstatus == 1 %}

                        <div class="hala-qr">

                            <img
                                src="data:image/png;base64,{{ get_zatca_phase_1_qr_for_invoice(doc.name) }}"
                                alt="ZATCA QR"
                            >

                           

                        </div>

                    {% endif %}


            </td>
 


                   
        </tr>

    </table>


    {# TERMS AND CONDITIONS #}

    {% if doc.terms %}
        <div class="hala-terms">
            <div class="bold">
                الشروط والأحكام / Terms & Conditions
            </div>

            <div>
                {{ doc.terms }}
            </div>
        </div>
    {% endif %}


    {# ZATCA QR AND FOOTER #}

   
    {# LETTERHEAD FOOTER #}

    {% if not no_letterhead and footer %}
        <div class="letter-head-footer" style="margin-top:12px;">
            {{ footer }}
        </div>
    {% endif %}

</div>
